import pandas as pd
import numpy as np
import re

# Load data
df = pd.read_csv('benchmark/data.csv')

# Clean price columns
def clean_price(x):
    if pd.isna(x):
        return np.nan
    return float(re.sub(r'[₹,]', '', str(x)))

def clean_discount(x):
    if pd.isna(x):
        return np.nan
    return float(re.sub(r'%', '', str(x)))

def clean_rating_count(x):
    if pd.isna(x):
        return np.nan
    return int(re.sub(r',', '', str(x)))

def clean_rating(x):
    if pd.isna(x):
        return np.nan
    # Some ratings might have pipe characters or be malformed
    s = str(x).strip()
    # Take first valid float if there are multiple
    if '|' in s:
        s = s.split('|')[0].strip()
    try:
        return float(s)
    except:
        return np.nan

df['discounted_price_num'] = df['discounted_price'].apply(clean_price)
df['actual_price_num'] = df['actual_price'].apply(clean_price)
df['discount_percentage_num'] = df['discount_percentage'].apply(clean_discount)
df['rating_num'] = df['rating'].apply(clean_rating)
df['rating_count_num'] = df['rating_count'].apply(clean_rating_count)

# Extract top-level category
df['top_category'] = df['category'].apply(lambda x: str(x).split('|')[0] if pd.notna(x) else 'Unknown')

# Check for issues
print("Cleaned data summary:")
print(df[['discounted_price_num','actual_price_num','discount_percentage_num','rating_num','rating_count_num']].describe())
print("\nTop categories:")
print(df['top_category'].value_counts().head(15))
print("\nRating distribution:")
print(df['rating_num'].value_counts().sort_index())
print("\nRows with valid ratings:", df['rating_num'].notna().sum())
print("Rows with valid rating_count:", df['rating_count_num'].notna().sum())
print("Rows with valid prices:", df['discounted_price_num'].notna().sum())
